 blockingReason(taskId:string):string|null{const task=this.task(taskId);if(!task)return null;const fleet=this.fleet(String(task.fleet_id));if(fleet.status!=='running')return 'Start or resume the whole fleet from Agent Fleet.';if(fleet.mode==='local_website'&&!this.labState().ready)return 'Start the synthetic training website before resuming this fleet.';if(task.preparation!=='ready')return 'Exact fleet inputs are not ready; resume the fleet to retry preparation.';for(const id of this.allowedInputVersionIds(taskId)!){if(!this.row("SELECT 1 FROM task_artifacts b JOIN artifact_versions v ON v.id=b.version_id JOIN artifacts a ON a.id=v.artifact_id WHERE b.task_id=? AND b.version_id=? AND b.role='input' AND a.visibility='shared' AND v.status='ready'",taskId,id))return 'An exact fleet input is missing.';try{this.projects.assertAgentVersion(String(task.agent_id),id);}catch{return 'Fleet agents and evidence must remain within their original project.';}}return null;}
